using ProjectTracker.Web.Services;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Hosting;
using Xunit;

namespace ProjectTracker.Web.Tests;

public class SecurityTests
{
    // Generated by the ORIGINAL Node.js implementation (lib/password.ts) for the password below.
    private const string NodeScryptHash = "scrypt$16384$8$1$1_zTBwMpnWsmpXrfoKpwhw$o7wREehC8i8oEKI8T8PXD2c4pjVfbuj5hxEb5dHQ5SI3aUjCmC9Fi4fMcE2Iq9Pdt5ykG8Ge5sVSPpebg5kbhA";

    [Fact]
    public void Scrypt_hash_written_by_the_Node_app_verifies()
    {
        Assert.Equal(new PasswordHasher.Verification(true, false), PasswordHasher.Verify(NodeScryptHash, "Vector#Pass-123"));
        Assert.False(PasswordHasher.Verify(NodeScryptHash, "wrong").Valid);
    }

    [Fact]
    public void New_hashes_round_trip_and_are_salted()
    {
        var a = PasswordHasher.Hash("Correct#Horse9");
        var b = PasswordHasher.Hash("Correct#Horse9");
        Assert.StartsWith("scrypt$16384$8$1$", a);
        Assert.NotEqual(a, b);
        Assert.True(PasswordHasher.Verify(a, "Correct#Horse9").Valid);
        Assert.False(PasswordHasher.Verify(a, "Correct#Horse8").Valid);
    }

    [Fact]
    public void Legacy_plain_text_is_accepted_once_and_flagged_for_rehash()
    {
        Assert.Equal(new PasswordHasher.Verification(true, true), PasswordHasher.Verify("plain-old", "plain-old"));
        Assert.False(PasswordHasher.Verify("plain-old", "other").Valid);
        Assert.False(PasswordHasher.Verify(null, "x").Valid);
        Assert.False(PasswordHasher.Verify("scrypt$1$2$3$x$y", "x").Valid);   // wrong parameters are rejected
    }

    private static SessionTokens Tokens(string? secret) =>
        new(new AppConfig(new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string, string?> { ["SESSION_SECRET"] = secret }).Build(), new FakeEnvironment()));

    [Fact]
    public void Session_tokens_are_signed_expiring_and_fail_closed()
    {
        var tokens = Tokens(new string('s', 40));
        var token = tokens.SignSession("11111111-1111-1111-1111-111111111111", "admin", "مدير", "22222222-2222-2222-2222-222222222222", "password", 60);
        var session = tokens.VerifySession(token);
        Assert.NotNull(session);
        Assert.Equal("admin", session!.Role);

        // tampering with the body or the signature invalidates it
        var parts = token.Split('.');
        Assert.Null(tokens.VerifySession($"{parts[0]}x.{parts[1]}"));
        Assert.Null(tokens.VerifySession($"{parts[0]}.{parts[1]}x"));
        Assert.Null(tokens.VerifySession(null));
        Assert.Null(tokens.VerifySession("garbage"));

        // another secret cannot verify it, and an expired token is refused
        Assert.Null(Tokens(new string('t', 40)).VerifySession(token));
        Assert.Null(tokens.VerifySession(tokens.SignSession("1", "admin", "x", "s", "password", -10)));

        // no (or a too short) secret: nothing is issued and nothing is accepted
        Assert.Throws<InvalidOperationException>(() => Tokens("short").SignSession("1", "admin", "x", "s", "password", 60));
        Assert.Null(Tokens("short").VerifySession(token));
    }

    private sealed class FakeEnvironment : IHostEnvironment
    {
        public string EnvironmentName { get; set; } = Environments.Development;
        public string ApplicationName { get; set; } = "test";
        public string ContentRootPath { get; set; } = ".";
        public Microsoft.Extensions.FileProviders.IFileProvider ContentRootFileProvider { get; set; } = new Microsoft.Extensions.FileProviders.NullFileProvider();
    }
}
